[
  {
    "proname": "create_notebook_badge",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.create_notebook_badge(p_bronze_notebook_id uuid, p_badge_type text)\n RETURNS uuid\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  new_badge_id UUID;\nBEGIN\n  -- Create the badge\n  INSERT INTO notebook_badges (bronze_notebook_id, badge_type)\n  VALUES (p_bronze_notebook_id, p_badge_type)\n  RETURNING id INTO new_badge_id;\n  \n  RETURN new_badge_id;\nEND;\n$function$\n"
  },
  {
    "proname": "create_notebook_with_pages",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.create_notebook_with_pages(p_user_id uuid, p_title text, p_language text, p_language_code text, p_words_per_day integer DEFAULT 20)\n RETURNS notebooks\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    new_notebook notebooks%ROWTYPE;\n    current_date DATE := CURRENT_DATE;\n    i INTEGER;\nBEGIN\n    -- Create the notebook\n    INSERT INTO notebooks (\n        user_id,\n        title,\n        language,\n        language_code,\n        words_per_day,\n        notebook_level,\n        settings\n    ) VALUES (\n        p_user_id,\n        p_title,\n        p_language,\n        p_language_code,\n        p_words_per_day,\n        'bronze'::notebook_level_enum,\n        '{}'::jsonb\n    ) RETURNING * INTO new_notebook;\n    \n    -- Create 200 pages\n    FOR i IN 1..200 LOOP\n        INSERT INTO pages (\n            notebook_id,\n            page_number,\n            date_created,\n            target_round,\n            words_count,\n            is_completed,\n            is_unlocked,\n            unlock_date,\n            next_review_date\n        ) VALUES (\n            new_notebook.id,\n            i,\n            current_date,\n            '1'::round_number,\n            0,\n            false,\n            CASE \n                WHEN i = 1 THEN true  -- First page is unlocked\n                ELSE false            -- All others locked initially\n            END,\n            CASE \n                WHEN i = 1 THEN current_date  -- First page unlocks today\n                ELSE current_date + (i - 1)   -- Each subsequent page unlocks one day later\n            END,\n            null\n        );\n    END LOOP;\n    \n    RETURN new_notebook;\nEND;\n$function$\n"
  },
  {
    "proname": "get_user_all_notebooks_with_stats",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_user_all_notebooks_with_stats(p_user_id uuid)\n RETURNS TABLE(id uuid, title text, language text, language_code text, words_per_day integer, notebook_level text, created_at timestamp with time zone, last_used_at timestamp with time zone, pages_count bigint, total_words bigint, words_ready_for_review bigint)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  RETURN QUERY\n  SELECT \n    n.id,\n    n.title,\n    n.language,\n    n.language_code,\n    n.words_per_day,\n    n.notebook_level::text,\n    n.created_at,\n    n.last_used_at,\n    COUNT(DISTINCT p.id) as pages_count,\n    COUNT(DISTINCT w.id) as total_words,\n    COUNT(DISTINCT CASE \n      WHEN w.review_date <= CURRENT_DATE AND w.is_mastered = false \n      THEN w.id \n      ELSE NULL \n    END) as words_ready_for_review\n  FROM notebooks n\n  LEFT JOIN pages p ON n.id = p.notebook_id\n  LEFT JOIN words w ON n.id = w.notebook_id\n  WHERE n.user_id = p_user_id AND n.is_active = true\n  GROUP BY n.id, n.title, n.language, n.language_code, n.words_per_day, n.notebook_level, n.created_at, n.last_used_at\n  ORDER BY n.last_used_at DESC, n.created_at DESC;\nEND;\n$function$\n"
  },
  {
    "proname": "create_default_notification_settings",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.create_default_notification_settings()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    INSERT INTO user_notification_settings (user_id)\n    VALUES (NEW.id)\n    ON CONFLICT (user_id) DO NOTHING;\n    RETURN NEW;\nEND;\n$function$\n"
  },
  {
    "proname": "update_page_after_review",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.update_page_after_review(p_page_id uuid, p_failed_words_count integer, p_current_date date DEFAULT CURRENT_DATE)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    page_record pages%ROWTYPE;\n    notebook_record notebooks%ROWTYPE;\n    next_review_date DATE;\nBEGIN\n    -- Get page and notebook details\n    SELECT * INTO page_record FROM pages WHERE id = p_page_id;\n    SELECT * INTO notebook_record FROM notebooks WHERE id = page_record.notebook_id;\n    \n    IF page_record.page_current_round < 4 THEN\n        -- Advance to next round\n        next_review_date := p_current_date + INTERVAL '14 days';\n        \n        UPDATE pages \n        SET \n            page_current_round = page_current_round + 1,\n            page_review_date = next_review_date\n        WHERE id = p_page_id;\n        \n        RETURN TRUE;\n    ELSE\n        -- Round 4 completed - check if migration needed\n        IF p_failed_words_count > 0 THEN\n            -- Mark page as ready for migration\n            UPDATE pages \n            SET page_status = 'migrated'\n            WHERE id = p_page_id;\n        ELSE\n            -- All words mastered - mark page as completed\n            UPDATE pages \n            SET page_status = 'completed'\n            WHERE id = p_page_id;\n        END IF;\n        \n        RETURN FALSE; -- No more reviews for this page\n    END IF;\nEND;\n$function$\n"
  },
  {
    "proname": "update_page_review_result",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.update_page_review_result(p_page_id uuid, p_remembered boolean, p_current_date date DEFAULT CURRENT_DATE)\n RETURNS TABLE(badge_acquired text, migration_triggered boolean)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  page_info RECORD;\n  next_review_date DATE;\n  migration_needed BOOLEAN := FALSE;\n  new_badge_type TEXT := NULL;\nBEGIN\n  -- Get page info\n  SELECT p.current_round, p.badge_id, nb.badge_type, nb.bronze_notebook_id\n  INTO page_info\n  FROM pages p\n  JOIN notebook_badges nb ON p.badge_id = nb.id\n  WHERE p.id = p_page_id;\n  \n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Page not found or not a badge page';\n  END IF;\n  \n  -- Calculate next review date (14 days from current)\n  next_review_date := p_current_date + INTERVAL '14 days';\n  \n  IF p_remembered THEN\n    -- All words in page are mastered\n    UPDATE words \n    SET \n      is_mastered = true,\n      status = 'mastered',\n      times_reviewed = times_reviewed + 1,\n      last_reviewed = p_current_date,\n      updated_at = NOW()\n    WHERE page_id = p_page_id;\n    \n    -- Mark page as completed\n    UPDATE pages \n    SET \n      status = 'completed',\n      updated_at = NOW()\n    WHERE id = p_page_id;\n  ELSE\n    -- Page forgotten - check if this is Round 4 failure\n    IF page_info.current_round >= 4 THEN\n      -- Round 4 failure - mark for migration\n      UPDATE pages \n      SET \n        status = 'failed',\n        current_round = page_info.current_round,\n        times_reviewed = times_reviewed + 1,\n        last_reviewed = p_current_date,\n        updated_at = NOW()\n      WHERE id = p_page_id;\n      \n      migration_needed := TRUE;\n      \n      -- Determine what badge will be acquired\n      IF page_info.badge_type = 'silver' THEN\n        new_badge_type := 'gold';\n      END IF;\n    ELSE\n      -- Advance to next round\n      UPDATE pages \n      SET \n        current_round = page_info.current_round + 1,\n        review_date = next_review_date,\n        status = 'ready_for_review',\n        times_reviewed = times_reviewed + 1,\n        last_reviewed = p_current_date,\n        updated_at = NOW()\n      WHERE id = p_page_id;\n      \n      -- Update word review counts\n      UPDATE words \n      SET \n        times_reviewed = times_reviewed + 1,\n        last_reviewed = p_current_date,\n        updated_at = NOW()\n      WHERE page_id = p_page_id;\n    END IF;\n  END IF;\n  \n  RETURN QUERY SELECT new_badge_type, migration_needed;\nEND;\n$function$\n"
  },
  {
    "proname": "get_notebook_badges",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_notebook_badges(p_bronze_notebook_id uuid)\n RETURNS TABLE(id uuid, badge_type text, created_at timestamp with time zone, total_words integer, active_pages_count integer, reviewable_pages_count bigint)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  RETURN QUERY\n  SELECT \n    nb.id,\n    nb.badge_type,\n    nb.created_at,\n    nb.total_words,\n    nb.active_pages_count,\n    COALESCE(\n      (SELECT COUNT(*) \n       FROM pages p \n       WHERE p.badge_id = nb.id \n       AND p.review_date IS NOT NULL \n       AND p.review_date <= NOW()\n      ), 0\n    ) as reviewable_pages_count\n  FROM notebook_badges nb\n  WHERE nb.bronze_notebook_id = p_bronze_notebook_id\n  ORDER BY nb.badge_type;\nEND;\n$function$\n"
  },
  {
    "proname": "get_words_with_badge_level",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_words_with_badge_level(p_user_id uuid)\n RETURNS TABLE(id uuid, word text, translation text, meaning text, example_sentence text, notes text, current_round integer, created_at timestamp with time zone, notebook_id uuid, page_id uuid, notebook_title text, notebook_language text, notebook_level text, badge_type text, review_type text)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  RETURN QUERY\n  SELECT \n    w.id,\n    w.word,\n    w.translation,\n    w.meaning,\n    w.example_sentence,\n    w.notes,\n    w.current_round,\n    w.created_at,\n    COALESCE(n.id, nb.bronze_notebook_id) as notebook_id,\n    w.page_id,\n    COALESCE(n.title, bn.title) as notebook_title,\n    COALESCE(n.language, bn.language) as notebook_language,\n    COALESCE(n.notebook_level, 'bronze') as notebook_level,\n    COALESCE(nb.badge_type, 'bronze') as badge_type,\n    CASE \n      WHEN n.id IS NOT NULL THEN 'word'\n      ELSE 'page'\n    END as review_type\n  FROM words w\n  LEFT JOIN pages p ON w.page_id = p.id\n  LEFT JOIN notebooks n ON p.notebook_id = n.id AND n.user_id = p_user_id\n  LEFT JOIN notebook_badges nb ON p.badge_id = nb.id\n  LEFT JOIN notebooks bn ON nb.bronze_notebook_id = bn.id AND bn.user_id = p_user_id\n  WHERE (\n    -- Bronze words (individual review)\n    (n.id IS NOT NULL AND w.review_date <= CURRENT_DATE AND w.status = 'learning')\n    OR\n    -- Silver/Gold words (page-based review)\n    (nb.id IS NOT NULL AND p.review_date <= NOW() AND p.status = 'ready_for_review')\n  )\n  ORDER BY w.created_at;\nEND;\n$function$\n"
  },
  {
    "proname": "run_badge_migrations",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.run_badge_migrations()\n RETURNS TABLE(bronze_to_silver_words integer, silver_to_gold_pages integer, badges_created integer)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  bronze_migration RECORD;\n  silver_migration RECORD;\nBEGIN\n  -- Run Bronze to Silver migration\n  SELECT * INTO bronze_migration FROM migrate_failed_bronze_words_to_silver();\n  \n  -- Run Silver to Gold migration  \n  SELECT * INTO silver_migration FROM migrate_failed_silver_pages_to_gold();\n  \n  RETURN QUERY SELECT \n    bronze_migration.words_migrated,\n    silver_migration.pages_migrated,\n    bronze_migration.badges_created + silver_migration.badges_created;\nEND;\n$function$\n"
  },
  {
    "proname": "archive_gold_failures",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.archive_gold_failures(p_gold_notebook_id uuid, p_failed_word_ids uuid[])\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    archived_count INTEGER;\nBEGIN\n    -- Mark Gold Round 4 failures as \"super_hard\"\n    UPDATE words \n    SET \n        status = 'super_hard',\n        updated_at = now()\n    WHERE id = ANY(p_failed_word_ids)\n      AND notebook_id = p_gold_notebook_id;\n    \n    GET DIAGNOSTICS archived_count = ROW_COUNT;\n    \n    RETURN archived_count;\nEND;\n$function$\n"
  },
  {
    "proname": "get_today_page",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_today_page(notebook_id_param uuid, current_date_param date)\n RETURNS TABLE(id uuid, page_number integer, words_count integer, is_unlocked boolean, unlock_date date)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        p.id,\n        p.page_number,\n        COALESCE(word_counts.word_count, 0) as words_count,\n        p.is_unlocked,\n        p.unlock_date\n    FROM pages p\n    LEFT JOIN (\n        SELECT \n            page_id,\n            COUNT(*) as word_count\n        FROM words \n        WHERE created_at::date = current_date_param\n        GROUP BY page_id\n    ) word_counts ON p.id = word_counts.page_id\n    WHERE p.notebook_id = notebook_id_param\n    AND p.unlock_date = current_date_param\n    AND p.is_unlocked = true\n    LIMIT 1;\nEND;\n$function$\n"
  },
  {
    "proname": "get_review_words_count",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_review_words_count(notebook_id_param uuid, current_date_param date)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    word_count INTEGER;\nBEGIN\n    SELECT COUNT(*)\n    INTO word_count\n    FROM words w\n    INNER JOIN pages p ON w.page_id = p.id\n    WHERE p.notebook_id = notebook_id_param\n    AND w.is_mastered = false\n    AND (\n        -- Words with review_date that's due\n        (w.review_date IS NOT NULL AND w.review_date::date <= current_date_param)\n        OR\n        -- Fallback: words created 14+ days ago without review_date\n        (w.review_date IS NULL AND w.created_at::date <= current_date_param - INTERVAL '14 days')\n    )\n    AND (\n        -- Not reviewed today\n        w.last_reviewed IS NULL \n        OR w.last_reviewed::date < current_date_param\n    );\n    \n    RETURN COALESCE(word_count, 0);\nEND;\n$function$\n"
  },
  {
    "proname": "get_user_activity_today",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_user_activity_today(user_id_param uuid, current_date_param date)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    activity_count INTEGER := 0;\n    words_added INTEGER := 0;\n    reviews_done INTEGER := 0;\nBEGIN\n    -- Count words added today\n    SELECT COUNT(*)\n    INTO words_added\n    FROM words w\n    INNER JOIN pages p ON w.page_id = p.id\n    INNER JOIN notebooks n ON p.notebook_id = n.id\n    WHERE n.user_id = user_id_param\n    AND w.created_at::date = current_date_param;\n    \n    -- Count reviews done today\n    SELECT COUNT(*)\n    INTO reviews_done\n    FROM words w\n    INNER JOIN pages p ON w.page_id = p.id\n    INNER JOIN notebooks n ON p.notebook_id = n.id\n    WHERE n.user_id = user_id_param\n    AND w.last_reviewed::date = current_date_param;\n    \n    activity_count := words_added + reviews_done;\n    \n    RETURN activity_count;\nEND;\n$function$\n"
  },
  {
    "proname": "get_user_notification_settings",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_user_notification_settings(user_id_param uuid)\n RETURNS TABLE(enable_notifications boolean, enable_daily_reminders boolean, enable_progress_reminders boolean, enable_review_reminders boolean, enable_streak_protection boolean, daily_reminder_time time without time zone, progress_reminder_time time without time zone, review_reminder_time time without time zone, streak_reminder_time time without time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        uns.enable_notifications,\n        uns.enable_daily_reminders,\n        uns.enable_progress_reminders,\n        uns.enable_review_reminders,\n        uns.enable_streak_protection,\n        uns.daily_reminder_time,\n        uns.progress_reminder_time,\n        uns.review_reminder_time,\n        uns.streak_reminder_time\n    FROM user_notification_settings uns\n    WHERE uns.user_id = user_id_param;\nEND;\n$function$\n"
  },
  {
    "proname": "get_notebook_archives_summary",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_notebook_archives_summary(p_notebook_id uuid)\n RETURNS TABLE(cycle_number integer, words_count integer, completed_at timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        na.cycle_number,\n        na.words_count,\n        na.completed_at\n    FROM notebook_archives na\n    WHERE na.notebook_id = p_notebook_id\n    ORDER BY na.cycle_number DESC;\nEND;\n$function$\n"
  },
  {
    "proname": "store_notification_history",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.store_notification_history(notification_id_param text, user_id_param uuid, type_param text, title_param text, body_param text, data_param jsonb DEFAULT '{}'::jsonb, scheduled_at_param timestamp with time zone DEFAULT NULL::timestamp with time zone, sent_at_param timestamp with time zone DEFAULT NULL::timestamp with time zone)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    INSERT INTO notification_history (\n        id,\n        user_id,\n        type,\n        title,\n        body,\n        data,\n        scheduled_at,\n        sent_at\n    ) VALUES (\n        notification_id_param,\n        user_id_param,\n        type_param,\n        title_param,\n        body_param,\n        data_param,\n        scheduled_at_param,\n        sent_at_param\n    )\n    ON CONFLICT (id) DO UPDATE SET\n        sent_at = COALESCE(sent_at_param, notification_history.sent_at),\n        updated_at = NOW();\nEND;\n$function$\n"
  },
  {
    "proname": "mark_notification_read",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.mark_notification_read(notification_id_param text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    UPDATE notification_history \n    SET read_at = NOW()\n    WHERE id = notification_id_param\n    AND read_at IS NULL;\nEND;\n$function$\n"
  },
  {
    "proname": "mark_notification_clicked",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.mark_notification_clicked(notification_id_param text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    UPDATE notification_history \n    SET clicked_at = NOW(),\n        read_at = COALESCE(read_at, NOW())\n    WHERE id = notification_id_param;\nEND;\n$function$\n"
  },
  {
    "proname": "get_user_notification_history",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_user_notification_history(user_id_param uuid, limit_param integer DEFAULT 50, offset_param integer DEFAULT 0)\n RETURNS TABLE(id text, type text, title text, body text, data jsonb, scheduled_at timestamp with time zone, sent_at timestamp with time zone, read_at timestamp with time zone, clicked_at timestamp with time zone, created_at timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        nh.id,\n        nh.type,\n        nh.title,\n        nh.body,\n        nh.data,\n        nh.scheduled_at,\n        nh.sent_at,\n        nh.read_at,\n        nh.clicked_at,\n        nh.created_at\n    FROM notification_history nh\n    WHERE nh.user_id = user_id_param\n    AND nh.sent_at IS NOT NULL\n    ORDER BY nh.sent_at DESC, nh.created_at DESC\n    LIMIT limit_param\n    OFFSET offset_param;\nEND;\n$function$\n"
  },
  {
    "proname": "get_unread_notification_count",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_unread_notification_count(user_id_param uuid)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    unread_count INTEGER;\nBEGIN\n    SELECT COUNT(*)\n    INTO unread_count\n    FROM notification_history\n    WHERE user_id = user_id_param\n    AND sent_at IS NOT NULL\n    AND read_at IS NULL;\n    \n    RETURN COALESCE(unread_count, 0);\nEND;\n$function$\n"
  },
  {
    "proname": "mark_all_notifications_read",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.mark_all_notifications_read(user_id_param uuid)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    updated_count INTEGER;\nBEGIN\n    UPDATE notification_history \n    SET read_at = NOW()\n    WHERE user_id = user_id_param\n    AND read_at IS NULL\n    AND sent_at IS NOT NULL;\n    \n    GET DIAGNOSTICS updated_count = ROW_COUNT;\n    RETURN updated_count;\nEND;\n$function$\n"
  },
  {
    "proname": "activate_subscription",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.activate_subscription(p_user_id uuid, p_subscription_type text, p_duration_days integer)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    UPDATE profiles\n    SET \n        subscription_status = p_subscription_type,\n        subscription_activated_at = NOW(),\n        subscription_expires_at = NOW() + (p_duration_days || ' days')::INTERVAL,\n        updated_at = NOW()\n    WHERE id = p_user_id;\n    \n    RETURN FOUND;\nEND;\n$function$\n"
  },
  {
    "proname": "archive_and_reset_notebook",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.archive_and_reset_notebook(p_notebook_id uuid)\n RETURNS TABLE(archived_words_count integer, new_cycle_number integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    user_id UUID;\n    words_count INTEGER;\n    next_cycle_number INTEGER;\nBEGIN\n    -- Get user ID\n    SELECT n.user_id INTO user_id\n    FROM notebooks n\n    WHERE n.id = p_notebook_id;\n    \n    -- Get count of words to archive\n    SELECT COUNT(*) INTO words_count\n    FROM words w\n    WHERE w.notebook_id = p_notebook_id AND w.is_archived = FALSE;\n    \n    -- Get next cycle number\n    SELECT COALESCE(MAX(cycle_number), 0) + 1 INTO next_cycle_number\n    FROM notebook_archives\n    WHERE notebook_id = p_notebook_id;\n    \n    -- Archive all current words\n    UPDATE words\n    SET \n        is_archived = TRUE,\n        archived_notebook_id = p_notebook_id,\n        archived_at = NOW(),\n        archive_cycle_number = next_cycle_number,\n        page_id = NULL  -- Decouple from pages\n    WHERE notebook_id = p_notebook_id AND is_archived = FALSE;\n    \n    -- Delete all pages to start fresh\n    DELETE FROM pages WHERE notebook_id = p_notebook_id;\n    \n    -- Create archive record\n    INSERT INTO notebook_archives (user_id, notebook_id, cycle_number, words_count)\n    VALUES (user_id, p_notebook_id, next_cycle_number, words_count);\n    \n    -- Create fresh pages 1-15\n    INSERT INTO pages (notebook_id, page_number, status, created_at, unlocked_at)\n    SELECT \n        p_notebook_id,\n        generate_series(1, 15),\n        CASE WHEN generate_series(1, 15) = 1 THEN 'unlocked' ELSE 'locked' END,\n        NOW(),\n        CASE WHEN generate_series(1, 15) = 1 THEN NOW() ELSE NULL END;\n    \n    RETURN QUERY SELECT words_count, next_cycle_number;\nEND;\n$function$\n"
  },
  {
    "proname": "get_archived_words",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_archived_words(p_notebook_id uuid)\n RETURNS TABLE(id uuid, word text, meaning text, notes text, archive_cycle_number integer, archived_at timestamp with time zone, round integer, status text, next_review_date timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        w.id,\n        w.word,\n        w.meaning,\n        w.notes,\n        w.archive_cycle_number,\n        w.archived_at,\n        w.round,\n        w.status,\n        w.next_review_date\n    FROM words w\n    WHERE w.archived_notebook_id = p_notebook_id \n    AND w.is_archived = TRUE\n    ORDER BY w.archive_cycle_number, w.archived_at;\nEND;\n$function$\n"
  },
  {
    "proname": "get_words_for_review",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_words_for_review(p_notebook_id uuid, p_current_date timestamp with time zone DEFAULT now())\n RETURNS TABLE(id uuid, word text, meaning text, notes text, round integer, status text, created_at timestamp with time zone, next_review_date timestamp with time zone, page_number integer, word_type text, example_sentence text, sentence_bold text, sentence_meaning text, meaning_bold text, ai_generated boolean, is_archived boolean, archive_cycle_number integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        w.id,\n        w.word,\n        w.meaning,\n        w.notes,\n        w.round,\n        w.status,\n        w.created_at,\n        w.next_review_date,\n        COALESCE(p.page_number, 0) as page_number,\n        w.word_type,\n        w.example_sentence,\n        w.sentence_bold,\n        w.sentence_meaning,\n        w.meaning_bold,\n        w.ai_generated,\n        w.is_archived,\n        w.archive_cycle_number\n    FROM words w\n    LEFT JOIN pages p ON p.id = w.page_id\n    WHERE (\n        -- Active words from this notebook\n        (w.notebook_id = p_notebook_id AND w.is_archived = FALSE)\n        OR \n        -- Archived words from this notebook\n        (w.archived_notebook_id = p_notebook_id AND w.is_archived = TRUE)\n    )\n    AND w.status IN ('learning', 'reviewing')\n    AND w.next_review_date <= p_current_date\n    ORDER BY w.next_review_date ASC, w.created_at ASC;\nEND;\n$function$\n"
  },
  {
    "proname": "get_user_stats_with_archives",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_user_stats_with_archives(p_user_id uuid)\n RETURNS TABLE(total_words_added integer, total_words_mastered integer, total_archived_words integer, total_archive_cycles integer, current_streak integer, longest_streak integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        (SELECT COUNT(*)::INTEGER FROM words w \n         JOIN notebooks n ON n.id = w.notebook_id \n         WHERE n.user_id = p_user_id),\n        (SELECT COUNT(*)::INTEGER FROM words w \n         JOIN notebooks n ON n.id = w.notebook_id \n         WHERE n.user_id = p_user_id AND w.status = 'mastered'),\n        (SELECT COUNT(*)::INTEGER FROM words w \n         WHERE w.archived_notebook_id IN (\n             SELECT id FROM notebooks WHERE user_id = p_user_id\n         ) AND w.is_archived = TRUE),\n        (SELECT COUNT(DISTINCT archive_cycle_number)::INTEGER FROM words w \n         WHERE w.archived_notebook_id IN (\n             SELECT id FROM notebooks WHERE user_id = p_user_id\n         ) AND w.is_archived = TRUE),\n        (SELECT streak_count FROM profiles WHERE id = p_user_id),\n        (SELECT longest_streak FROM profiles WHERE id = p_user_id);\nEND;\n$function$\n"
  },
  {
    "proname": "is_subscription_active",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.is_subscription_active(p_user_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    sub_status TEXT;\n    expires_at TIMESTAMPTZ;\nBEGIN\n    SELECT subscription_status, subscription_expires_at\n    INTO sub_status, expires_at\n    FROM profiles\n    WHERE id = p_user_id;\n    \n    -- Free users are not active\n    IF sub_status = 'free' OR sub_status IS NULL THEN\n        RETURN FALSE;\n    END IF;\n    \n    -- Check if subscription hasn't expired\n    RETURN expires_at IS NULL OR expires_at > NOW();\nEND;\n$function$\n"
  },
  {
    "proname": "update_page_with_completion_check",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.update_page_with_completion_check(p_page_id uuid, p_daily_limit integer, p_added_words_count integer DEFAULT 0)\n RETURNS json\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_total_words INTEGER;\n    v_is_completed BOOLEAN;\n    v_review_date DATE;\n    v_result JSON;\nBEGIN\n    -- Get the total count of words for this page\n    SELECT COUNT(*) INTO v_total_words\n    FROM words \n    WHERE page_id = p_page_id;\n    \n    -- Determine if page should be completed based on daily limit\n    v_is_completed := v_total_words >= p_daily_limit;\n    \n    -- Set review date only if page is completed\n    IF v_is_completed THEN\n        v_review_date := CURRENT_DATE + INTERVAL '14 days';\n    ELSE\n        v_review_date := NULL;\n    END IF;\n    \n    -- Update the page with correct stats\n    UPDATE pages \n    SET \n        words_count = v_total_words,\n        is_completed = v_is_completed,\n        next_review_date = v_review_date,\n        updated_at = NOW()\n    WHERE id = p_page_id;\n    \n    -- Log for debugging\n    RAISE LOG 'Page % updated: total_words=%, daily_limit=%, completed=%, review_date=%', \n        p_page_id, v_total_words, p_daily_limit, v_is_completed, v_review_date;\n    \n    -- Return debug information\n    v_result := json_build_object(\n        'page_id', p_page_id,\n        'total_words', v_total_words,\n        'daily_limit', p_daily_limit,\n        'is_completed', v_is_completed,\n        'review_date', v_review_date,\n        'added_words_count', p_added_words_count\n    );\n    \n    RETURN v_result;\nEND;\n$function$\n"
  },
  {
    "proname": "start_free_trial",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.start_free_trial(p_user_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    -- Start trial by setting trial_started_at and updating status\n    UPDATE profiles\n    SET \n        trial_started_at = NOW(),\n        subscription_status = 'trial',\n        updated_at = NOW()\n    WHERE id = p_user_id;\n    \n    RETURN FOUND;\nEND;\n$function$\n"
  },
  {
    "proname": "get_trial_days_remaining",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_trial_days_remaining(p_user_id uuid)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    trial_start TIMESTAMPTZ;\n    days_remaining INTEGER;\nBEGIN\n    SELECT trial_started_at INTO trial_start\n    FROM profiles\n    WHERE id = p_user_id;\n    \n    -- If no trial started, return 0\n    IF trial_start IS NULL THEN\n        RETURN 0;\n    END IF;\n    \n    -- Calculate days remaining (max 15)\n    days_remaining := GREATEST(0, 15 - EXTRACT(DAY FROM NOW() - trial_start)::INTEGER);\n    \n    RETURN days_remaining;\nEND;\n$function$\n"
  },
  {
    "proname": "add_words_to_page",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.add_words_to_page(p_page_id uuid, p_words jsonb)\n RETURNS SETOF words\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    word_record RECORD;\n    new_word words%ROWTYPE;\nBEGIN\n    -- Loop through the words array\n    FOR word_record IN SELECT * FROM jsonb_array_elements(p_words)\n    LOOP\n        -- Insert each word\n        INSERT INTO words (\n            page_id,\n            notebook_id,\n            word,\n            meaning,\n            translation,\n            notes,\n            position_in_page,\n            review_date\n        ) VALUES (\n            p_page_id,\n            (SELECT notebook_id FROM pages WHERE id = p_page_id),\n            (word_record.value->>'word')::TEXT,\n            (word_record.value->>'meaning')::TEXT,\n            (word_record.value->>'meaning')::TEXT, -- Copy meaning to translation for compatibility\n            (word_record.value->>'notes')::TEXT,\n            (word_record.value->>'position')::INTEGER,\n            CURRENT_DATE + INTERVAL '14 days' -- 14 days from now\n        ) RETURNING * INTO new_word;\n        \n        RETURN NEXT new_word;\n    END LOOP;\n    \n    -- Update page stats\n    UPDATE pages \n    SET \n        words_count = (SELECT COUNT(*) FROM words WHERE page_id = p_page_id),\n        is_completed = true,\n        next_review_date = CURRENT_DATE + INTERVAL '14 days'\n    WHERE id = p_page_id;\n    \n    RETURN;\nEND;\n$function$\n"
  },
  {
    "proname": "can_add_words_trial",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.can_add_words_trial(p_user_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    sub_status TEXT;\n    in_trial BOOLEAN;\nBEGIN\n    -- Get subscription status\n    SELECT subscription_status INTO sub_status\n    FROM profiles\n    WHERE id = p_user_id;\n    \n    -- Premium users can always add words\n    IF sub_status IN ('weekly', 'monthly', 'yearly') THEN\n        RETURN TRUE;\n    END IF;\n    \n    -- Check if user is in trial period\n    SELECT is_in_trial_period(p_user_id) INTO in_trial;\n    \n    -- Users can add words during trial, but not after trial expires\n    RETURN in_trial;\nEND;\n$function$\n"
  },
  {
    "proname": "get_bronze_round4_failures",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_bronze_round4_failures(p_notebook_id uuid)\n RETURNS TABLE(word_id uuid, word text, meaning text, translation text, notes text, original_page_id uuid, page_number integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT * FROM get_notebook_round4_failures(p_notebook_id, 'bronze');\nEND;\n$function$\n"
  },
  {
    "proname": "create_new_page",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.create_new_page(p_notebook_id uuid)\n RETURNS pages\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    next_page_number INTEGER;\n    new_page pages%ROWTYPE;\nBEGIN\n    -- Get the next page number\n    SELECT COALESCE(MAX(page_number), 0) + 1 \n    INTO next_page_number\n    FROM pages \n    WHERE notebook_id = p_notebook_id;\n    \n    -- Create the new page\n    INSERT INTO pages (\n        notebook_id,\n        page_number,\n        date_created,\n        target_round\n    ) VALUES (\n        p_notebook_id,\n        next_page_number,\n        CURRENT_DATE,\n        '1'::round_number\n    ) RETURNING * INTO new_page;\n    \n    RETURN new_page;\nEND;\n$function$\n"
  },
  {
    "proname": "get_words_for_review_v2",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_words_for_review_v2(p_notebook_id uuid)\n RETURNS TABLE(id uuid, word text, meaning text, translation text, notes text, current_round integer, status word_status, page_number integer, review_date date, created_at timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        w.id,\n        w.word,\n        w.meaning,\n        w.translation,\n        w.notes,\n        w.current_round,\n        w.status,\n        p.page_number,\n        w.review_date,\n        w.created_at\n    FROM words w\n    JOIN pages p ON w.page_id = p.id\n    WHERE p.notebook_id = p_notebook_id\n      AND w.status = 'learning'\n      AND w.review_date <= CURRENT_DATE\n      AND NOT w.is_mastered\n    ORDER BY w.review_date ASC, w.created_at ASC;\nEND;\n$function$\n"
  },
  {
    "proname": "get_user_stats",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_user_stats(user_id uuid DEFAULT NULL::uuid)\n RETURNS TABLE(total_notebooks bigint, total_words bigint, words_mastered bigint, current_streak integer, words_added_today bigint)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  target_user_id uuid := COALESCE(user_id, auth.uid());\nBEGIN\n  RETURN QUERY\n  SELECT \n    (SELECT COUNT(*) FROM notebooks nb WHERE nb.user_id = target_user_id)::bigint as total_notebooks,\n    (SELECT COUNT(*) FROM words w \n     JOIN notebooks nb ON w.notebook_id = nb.id \n     WHERE nb.user_id = target_user_id)::bigint as total_words,\n    (SELECT COUNT(*) FROM words w \n     JOIN notebooks nb ON w.notebook_id = nb.id \n     WHERE nb.user_id = target_user_id AND w.is_mastered = true)::bigint as words_mastered,\n    (SELECT streak_count FROM profiles p WHERE p.id = target_user_id) as current_streak,\n    (SELECT COUNT(*) FROM words w \n     JOIN notebooks nb ON w.notebook_id = nb.id \n     WHERE nb.user_id = target_user_id \n     AND DATE(w.created_at) = CURRENT_DATE)::bigint as words_added_today;\nEND;\n$function$\n"
  },
  {
    "proname": "update_updated_at_column",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.update_updated_at_column()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    NEW.updated_at = NOW();\n    RETURN NEW;\nEND;\n$function$\n"
  },
  {
    "proname": "create_notebook",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.create_notebook(p_title text, p_language text, p_language_code text, p_words_per_day integer DEFAULT 20)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  new_notebook_id uuid;\n  user_subscription_status text;\n  notebook_count integer;\nBEGIN\n  -- Check user's subscription status\n  SELECT subscription_status INTO user_subscription_status\n  FROM profiles WHERE id = auth.uid();\n  \n  -- Count existing notebooks\n  SELECT COUNT(*) INTO notebook_count\n  FROM notebooks WHERE user_id = auth.uid();\n  \n  -- Check limits for free users\n  IF user_subscription_status = 'free' AND notebook_count >= 3 THEN\n    RAISE EXCEPTION 'Free users can only create up to 3 notebooks. Upgrade to Premium for unlimited notebooks.';\n  END IF;\n  \n  -- Create the notebook\n  INSERT INTO notebooks (\n    user_id,\n    title,\n    language,\n    language_code,\n    words_per_day,\n    notebook_level\n  ) VALUES (\n    auth.uid(),\n    p_title,\n    p_language,\n    p_language_code,\n    p_words_per_day,\n    'bronze'\n  ) RETURNING id INTO new_notebook_id;\n  \n  RETURN new_notebook_id;\nEND;\n$function$\n"
  },
  {
    "proname": "update_user_profile",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.update_user_profile(p_display_name text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  UPDATE profiles \n  SET \n    display_name = COALESCE(p_display_name, display_name),\n    avatar_url = COALESCE(p_avatar_url, avatar_url),\n    updated_at = NOW()\n  WHERE id = auth.uid();\n  \n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Profile not found';\n  END IF;\nEND;\n$function$\n"
  },
  {
    "proname": "unlock_todays_page",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.unlock_todays_page(p_user_id uuid)\n RETURNS SETOF pages\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    -- Unlock all pages that should be unlocked today or before\n    UPDATE pages \n    SET is_unlocked = true \n    WHERE unlock_date <= CURRENT_DATE \n      AND is_unlocked = false\n      AND notebook_id IN (\n          SELECT id FROM notebooks WHERE user_id = p_user_id\n      );\n    \n    -- Return the newly unlocked pages\n    RETURN QUERY\n    SELECT p.* FROM pages p\n    JOIN notebooks n ON p.notebook_id = n.id\n    WHERE n.user_id = p_user_id\n      AND p.unlock_date = CURRENT_DATE\n      AND p.is_unlocked = true;\nEND;\n$function$\n"
  },
  {
    "proname": "get_user_notebooks",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_user_notebooks()\n RETURNS TABLE(id uuid, title text, language text, language_code text, words_per_day integer, notebook_level notebook_level_enum, total_words bigint, mastered_words bigint, pending_reviews bigint, todays_target integer, created_at timestamp with time zone, updated_at timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  RETURN QUERY\n  SELECT \n    n.id,\n    n.title,\n    n.language,\n    n.language_code,\n    n.words_per_day,\n    n.notebook_level,\n    COALESCE(stats.total_words, 0)::bigint as total_words,\n    COALESCE(stats.mastered_words, 0)::bigint as mastered_words,\n    COALESCE(reviews.pending_count, 0)::bigint as pending_reviews,\n    n.words_per_day as todays_target,\n    n.created_at,\n    n.updated_at\n  FROM notebooks n\n  LEFT JOIN (\n    SELECT \n      notebook_id,\n      COUNT(*) as total_words,\n      COUNT(CASE WHEN is_mastered THEN 1 END) as mastered_words\n    FROM words\n    GROUP BY notebook_id\n  ) stats ON n.id = stats.notebook_id\n  LEFT JOIN (\n    SELECT \n      notebook_id,\n      COUNT(*) as pending_count\n    FROM words\n    WHERE review_date <= CURRENT_DATE \n    AND is_mastered = false\n    GROUP BY notebook_id\n  ) reviews ON n.id = reviews.notebook_id\n  WHERE n.user_id = auth.uid()\n  ORDER BY n.updated_at DESC;\nEND;\n$function$\n"
  },
  {
    "proname": "add_words_to_notebook",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.add_words_to_notebook(p_notebook_id uuid, p_words jsonb)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  word_record jsonb;\n  words_added integer := 0;\n  review_date date;\nBEGIN\n  -- Check if user owns this notebook\n  IF NOT EXISTS (\n    SELECT 1 FROM notebooks \n    WHERE id = p_notebook_id AND user_id = auth.uid()\n  ) THEN\n    RAISE EXCEPTION 'Notebook not found or access denied';\n  END IF;\n  \n  -- Calculate review date (14 days from now)\n  review_date := CURRENT_DATE + INTERVAL '14 days';\n  \n  -- Insert each word\n  FOR word_record IN SELECT * FROM jsonb_array_elements(p_words)\n  LOOP\n    INSERT INTO words (\n      notebook_id,\n      word,\n      translation,\n      example_sentence,\n      notes,\n      current_round,\n      review_date\n    ) VALUES (\n      p_notebook_id,\n      word_record->>'word',\n      word_record->>'translation',\n      NULLIF(word_record->>'example_sentence', ''),\n      NULLIF(word_record->>'notes', ''),\n      1,\n      review_date\n    );\n    \n    words_added := words_added + 1;\n  END LOOP;\n  \n  -- Update notebook's updated_at timestamp\n  UPDATE notebooks \n  SET updated_at = NOW() \n  WHERE id = p_notebook_id;\n  \n  RETURN words_added;\nEND;\n$function$\n"
  },
  {
    "proname": "get_trial_days_remaining",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_trial_days_remaining(p_user_id uuid, p_current_date timestamp with time zone DEFAULT now())\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    trial_start TIMESTAMPTZ;\n    days_elapsed INTEGER;\n    days_remaining INTEGER;\nBEGIN\n    SELECT trial_started_at INTO trial_start\n    FROM profiles\n    WHERE id = p_user_id;\n    \n    -- If no trial started, return 0\n    IF trial_start IS NULL THEN\n        RETURN 0;\n    END IF;\n    \n    -- Calculate actual elapsed days using proper date arithmetic\n    days_elapsed := (p_current_date::date - trial_start::date);\n    \n    -- Calculate days remaining (max 15)\n    days_remaining := GREATEST(0, 15 - days_elapsed);\n    \n    RETURN days_remaining;\nEND;\n$function$\n"
  },
  {
    "proname": "migrate_words_to_gold",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.migrate_words_to_gold(p_silver_notebook_id uuid, p_gold_notebook_id uuid, p_failed_word_ids uuid[])\n RETURNS SETOF words\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    word_record RECORD;\n    new_word words%ROWTYPE;\n    gold_notebook notebooks%ROWTYPE;\n    current_page_id UUID;\n    words_in_current_page INTEGER := 0;\n    current_page_number INTEGER;\n    max_page_number INTEGER;\nBEGIN\n    -- Get Gold notebook details\n    SELECT * INTO gold_notebook FROM notebooks WHERE id = p_gold_notebook_id;\n    \n    -- Find the highest existing page number in Gold notebook\n    SELECT COALESCE(MAX(page_number), 0) INTO max_page_number\n    FROM pages \n    WHERE notebook_id = p_gold_notebook_id;\n    \n    -- Start from the next available page number\n    current_page_number := max_page_number + 1;\n    \n    -- Create first page in Gold notebook with page-based review fields\n    INSERT INTO pages (\n        notebook_id,\n        page_number,\n        date_created,\n        target_round,\n        page_completion_date,\n        page_current_round,\n        page_status,\n        page_review_date\n    ) VALUES (\n        p_gold_notebook_id,\n        current_page_number,\n        CURRENT_DATE,\n        '1'::round_number,\n        CURRENT_DATE,\n        1,\n        'active',\n        CURRENT_DATE + INTERVAL '14 days'\n    ) RETURNING id INTO current_page_id;\n    \n    -- Migrate each failed word\n    FOR word_record IN \n        SELECT w.*, p.page_number as silver_page_number\n        FROM words w\n        JOIN pages p ON w.page_id = p.id\n        WHERE w.id = ANY(p_failed_word_ids)\n        ORDER BY p.page_number, w.position_in_page\n    LOOP\n        -- Check if we need a new page\n        IF words_in_current_page >= gold_notebook.words_per_day THEN\n            current_page_number := current_page_number + 1;\n            words_in_current_page := 0;\n            \n            -- Create new page with page-based review fields\n            INSERT INTO pages (\n                notebook_id,\n                page_number,\n                date_created,\n                target_round,\n                page_completion_date,\n                page_current_round,\n                page_status,\n                page_review_date\n            ) VALUES (\n                p_gold_notebook_id,\n                current_page_number,\n                CURRENT_DATE,\n                '1'::round_number,\n                CURRENT_DATE,\n                1,\n                'active',\n                CURRENT_DATE + INTERVAL '14 days'\n            ) RETURNING id INTO current_page_id;\n        END IF;\n        \n        -- Insert word into Gold notebook (reset to Round 1)\n        INSERT INTO words (\n            notebook_id,\n            page_id,\n            word,\n            meaning,\n            translation,\n            notes,\n            current_round,\n            status,\n            review_date,\n            source_notebook_id, -- Keep original Bronze notebook ID\n            original_page_id,   -- Keep original Bronze page ID\n            position_in_page\n        ) VALUES (\n            p_gold_notebook_id,\n            current_page_id,\n            word_record.word,\n            word_record.meaning,\n            word_record.translation,\n            word_record.notes,\n            1, -- Reset to Round 1 in Gold\n            'learning',\n            CURRENT_DATE + INTERVAL '14 days', -- New 14-day timer\n            word_record.source_notebook_id, -- Preserve original Bronze ID\n            word_record.original_page_id,   -- Preserve original Bronze page ID\n            words_in_current_page + 1\n        ) RETURNING * INTO new_word;\n        \n        words_in_current_page := words_in_current_page + 1;\n        \n        -- Mark original Silver word as failed (moved to Gold)\n        UPDATE words \n        SET status = 'failed' \n        WHERE id = word_record.id;\n        \n        RETURN NEXT new_word;\n    END LOOP;\n    \n    -- Update page stats\n    UPDATE pages \n    SET \n        words_count = (SELECT COUNT(*) FROM words WHERE page_id = pages.id),\n        is_completed = (SELECT COUNT(*) FROM words WHERE page_id = pages.id) > 0\n    WHERE notebook_id = p_gold_notebook_id;\n    \n    RETURN;\nEND;\n$function$\n"
  },
  {
    "proname": "is_in_trial_period",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.is_in_trial_period(p_user_id uuid, p_current_date timestamp with time zone DEFAULT now())\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    trial_start TIMESTAMPTZ;\n    sub_status TEXT;\n    days_elapsed INTEGER;\nBEGIN\n    SELECT trial_started_at, subscription_status\n    INTO trial_start, sub_status\n    FROM profiles\n    WHERE id = p_user_id;\n    \n    -- If user has premium subscription, they're not in trial\n    IF sub_status IN ('weekly', 'monthly', 'yearly') THEN\n        RETURN FALSE;\n    END IF;\n    \n    -- If no trial started, user is not in trial\n    IF trial_start IS NULL THEN\n        RETURN FALSE;\n    END IF;\n    \n    -- Calculate elapsed days properly\n    days_elapsed := (p_current_date::date - trial_start::date);\n    \n    -- Trial is active if less than 15 days have elapsed\n    RETURN days_elapsed < 15;\nEND;\n$function$\n"
  },
  {
    "proname": "can_add_words_trial",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.can_add_words_trial(p_user_id uuid, p_current_date timestamp with time zone DEFAULT now())\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    sub_status TEXT;\n    in_trial BOOLEAN;\nBEGIN\n    -- Get subscription status\n    SELECT subscription_status INTO sub_status\n    FROM profiles\n    WHERE id = p_user_id;\n    \n    -- Premium users can always add words\n    IF sub_status IN ('weekly', 'monthly', 'yearly') THEN\n        RETURN TRUE;\n    END IF;\n    \n    -- Check if user is in trial period using corrected function\n    SELECT is_in_trial_period(p_user_id, p_current_date) INTO in_trial;\n    \n    -- Users can add words during trial, but not after trial expires\n    RETURN in_trial;\nEND;\n$function$\n"
