  {
    "proname": "get_daily_progress",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_daily_progress(p_start_date date DEFAULT (CURRENT_DATE - '30 days'::interval), p_end_date date DEFAULT CURRENT_DATE)\n RETURNS TABLE(date date, words_added bigint, words_reviewed bigint, words_mastered bigint, total_study_time integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  RETURN QUERY\n  WITH date_series AS (\n    SELECT generate_series(p_start_date, p_end_date, '1 day'::interval)::date as date\n  ),\n  daily_stats AS (\n    SELECT \n      DATE(w.created_at) as date,\n      COUNT(*) as words_added,\n      0::bigint as words_reviewed,\n      0::bigint as words_mastered\n    FROM words w\n    JOIN notebooks n ON w.notebook_id = n.id\n    WHERE n.user_id = auth.uid()\n      AND DATE(w.created_at) BETWEEN p_start_date AND p_end_date\n    GROUP BY DATE(w.created_at)\n    \n    UNION ALL\n    \n    SELECT \n      DATE(w.last_reviewed) as date,\n      0::bigint as words_added,\n      COUNT(*) as words_reviewed,\n      COUNT(CASE WHEN w.is_mastered AND DATE(w.updated_at) = DATE(w.last_reviewed) THEN 1 END) as words_mastered\n    FROM words w\n    JOIN notebooks n ON w.notebook_id = n.id\n    WHERE n.user_id = auth.uid()\n      AND w.last_reviewed IS NOT NULL\n      AND DATE(w.last_reviewed) BETWEEN p_start_date AND p_end_date\n    GROUP BY DATE(w.last_reviewed)\n  )\n  SELECT \n    ds.date,\n    COALESCE(SUM(daily_stats.words_added), 0)::bigint as words_added,\n    COALESCE(SUM(daily_stats.words_reviewed), 0)::bigint as words_reviewed,\n    COALESCE(SUM(daily_stats.words_mastered), 0)::bigint as words_mastered,\n    0 as total_study_time -- Placeholder for future implementation\n  FROM date_series ds\n  LEFT JOIN daily_stats ON ds.date = daily_stats.date\n  GROUP BY ds.date\n  ORDER BY ds.date;\nEND;\n$function$\n"
  },
  {
    "proname": "can_create_notebook_trial",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.can_create_notebook_trial(p_user_id uuid, p_current_date timestamp with time zone DEFAULT now())\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    existing_count INTEGER;\n    has_premium BOOLEAN;\nBEGIN\n    -- Check if user has premium subscription\n    SELECT subscription_status IN ('weekly', 'monthly', 'yearly') INTO has_premium\n    FROM profiles\n    WHERE id = p_user_id;\n    \n    -- Premium users have no limits\n    IF has_premium THEN\n        RETURN TRUE;\n    END IF;\n    \n    -- Count existing active notebooks\n    SELECT COUNT(*) INTO existing_count\n    FROM notebooks\n    WHERE user_id = p_user_id AND is_active = TRUE;\n    \n    -- Single notebook limit for trial/free users\n    RETURN existing_count = 0;\nEND;\n$function$\n"
  },
  {
    "proname": "is_in_trial_period",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.is_in_trial_period(p_user_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    trial_start TIMESTAMPTZ;\n    sub_status TEXT;\nBEGIN\n    SELECT trial_started_at, subscription_status\n    INTO trial_start, sub_status\n    FROM profiles\n    WHERE id = p_user_id;\n    \n    -- If user has premium subscription, they're not in trial\n    IF sub_status IN ('weekly', 'monthly', 'yearly') THEN\n        RETURN FALSE;\n    END IF;\n    \n    -- If no trial started, user is not in trial\n    IF trial_start IS NULL THEN\n        RETURN FALSE;\n    END IF;\n    \n    -- Check if trial period (15 days) has not expired\n    RETURN trial_start + INTERVAL '15 days' > NOW();\nEND;\n$function$\n"
  },
  {
    "proname": "can_create_notebook_trial",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.can_create_notebook_trial(p_user_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    existing_count INTEGER;\n    has_premium BOOLEAN;\nBEGIN\n    -- Check if user has premium subscription\n    SELECT subscription_status IN ('weekly', 'monthly', 'yearly') INTO has_premium\n    FROM profiles\n    WHERE id = p_user_id;\n    \n    -- Premium users have no limits\n    IF has_premium THEN\n        RETURN TRUE;\n    END IF;\n    \n    -- Count existing active notebooks\n    SELECT COUNT(*) INTO existing_count\n    FROM notebooks\n    WHERE user_id = p_user_id AND is_active = TRUE;\n    \n    -- Single notebook limit for trial/free users\n    RETURN existing_count = 0;\nEND;\n$function$\n"
