  {
    "proname": "check_subscription_limits",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.check_subscription_limits(p_user_id uuid)\n RETURNS TABLE(can_create_notebook boolean, notebook_count integer, notebook_limit integer, subscription_status text, is_premium boolean)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  user_subscription text;\n  current_notebook_count integer;\n  max_notebooks integer;\nBEGIN\n  -- Get user subscription status\n  SELECT profiles.subscription_status \n  INTO user_subscription\n  FROM profiles \n  WHERE id = p_user_id;\n  \n  -- Count user's notebooks\n  SELECT COUNT(*)::integer \n  INTO current_notebook_count\n  FROM notebooks \n  WHERE user_id = p_user_id;\n  \n  -- Determine limits based on subscription\n  IF user_subscription IN ('weekly', 'annual') THEN\n    max_notebooks := 999; -- Unlimited for premium users\n  ELSE\n    max_notebooks := 3; -- Free user limit\n  END IF;\n  \n  RETURN QUERY\n  SELECT \n    (current_notebook_count < max_notebooks) as can_create_notebook,\n    current_notebook_count as notebook_count,\n    max_notebooks as notebook_limit,\n    user_subscription as subscription_status,\n    (user_subscription IN ('weekly', 'annual')) as is_premium;\nEND;\n$function$\n"
  },
  {
    "proname": "delete_notebook",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.delete_notebook(p_notebook_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  -- Check if user owns this notebook\n  IF NOT EXISTS (\n    SELECT 1 FROM notebooks \n    WHERE id = p_notebook_id AND user_id = auth.uid()\n  ) THEN\n    RAISE EXCEPTION 'Notebook not found or access denied';\n  END IF;\n  \n  -- Delete all words in the notebook first (cascade will handle this, but explicit is better)\n  DELETE FROM words WHERE notebook_id = p_notebook_id;\n  \n  -- Delete the notebook\n  DELETE FROM notebooks WHERE id = p_notebook_id AND user_id = auth.uid();\nEND;\n$function$\n"
  },
  {
    "proname": "get_current_page",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_current_page(p_notebook_id uuid)\n RETURNS pages\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    current_page pages%ROWTYPE;\nBEGIN\n    -- First, unlock any pages that should be unlocked\n    UPDATE pages \n    SET is_unlocked = true \n    WHERE unlock_date <= CURRENT_DATE \n      AND is_unlocked = false\n      AND notebook_id = p_notebook_id;\n    \n    -- Get the highest unlocked page that's not completed\n    SELECT * INTO current_page\n    FROM pages\n    WHERE notebook_id = p_notebook_id\n      AND is_unlocked = true\n      AND is_completed = false\n    ORDER BY page_number ASC\n    LIMIT 1;\n    \n    -- If no incomplete unlocked page, get the next unlocked page\n    IF current_page.id IS NULL THEN\n        SELECT * INTO current_page\n        FROM pages\n        WHERE notebook_id = p_notebook_id\n          AND is_unlocked = true\n        ORDER BY page_number DESC\n        LIMIT 1;\n    END IF;\n    \n    RETURN current_page;\nEND;\n$function$\n"
  },
  {
    "proname": "update_word_review_result",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.update_word_review_result(p_word_id uuid, p_remembered boolean, p_current_date date DEFAULT CURRENT_DATE)\n RETURNS TABLE(success boolean, new_round integer, new_status text, review_date date, is_mastered boolean)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  word_record RECORD;\n  next_round INTEGER;\n  next_review_date DATE;\n  new_word_status TEXT;\n  mastered BOOLEAN := FALSE;\nBEGIN\n  -- Get current word state\n  SELECT current_round, status, times_reviewed\n  INTO word_record\n  FROM words \n  WHERE id = p_word_id;\n  \n  IF NOT FOUND THEN\n    RETURN QUERY SELECT FALSE, 0, 'not_found'::TEXT, NULL::DATE, FALSE;\n    RETURN;\n  END IF;\n  \n  -- Calculate next state based on review result\n  IF p_remembered THEN\n    -- Word remembered - mastered\n    new_word_status := 'mastered';\n    next_round := word_record.current_round;\n    next_review_date := NULL;\n    mastered := TRUE;\n  ELSE\n    -- Word forgotten - advance to next round\n    next_round := word_record.current_round + 1;\n    \n    IF next_round > 12 THEN\n      -- Even Gold Round 4 failures become mastered (max difficulty reached)\n      new_word_status := 'mastered';\n      next_review_date := NULL;\n      mastered := TRUE;\n      next_round := 12;  -- Cap at round 12\n    ELSE\n      -- Continue learning at next round\n      new_word_status := 'learning';\n      next_review_date := p_current_date + INTERVAL '14 days';\n      mastered := FALSE;\n    END IF;\n  END IF;\n  \n  -- Update the word\n  UPDATE words\n  SET \n    current_round = next_round::round_number,\n    status = new_word_status,\n    review_date = next_review_date,\n    last_reviewed = p_current_date,\n    times_reviewed = COALESCE(word_record.times_reviewed, 0) + 1,\n    is_mastered = mastered,\n    updated_at = NOW()\n  WHERE id = p_word_id;\n  \n  -- Return the result\n  RETURN QUERY SELECT TRUE, next_round, new_word_status, next_review_date, mastered;\nEND;\n$function$\n"
  },
  {
    "proname": "get_learning_insights",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_learning_insights()\n RETURNS TABLE(total_words_learned bigint, words_mastered_this_week bigint, average_mastery_rate numeric, most_productive_day text, current_streak integer, longest_streak integer, recommended_daily_target integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  user_profile_data profiles%ROWTYPE;\nBEGIN\n  -- Get user profile data\n  SELECT * INTO user_profile_data FROM profiles WHERE id = auth.uid();\n  \n  RETURN QUERY\n  WITH weekly_stats AS (\n    SELECT \n      COUNT(CASE WHEN w.is_mastered AND w.updated_at >= CURRENT_DATE - INTERVAL '7 days' THEN 1 END) as mastered_this_week\n    FROM words w\n    JOIN notebooks n ON w.notebook_id = n.id\n    WHERE n.user_id = auth.uid()\n  ),\n  daily_counts AS (\n    SELECT \n      EXTRACT(DOW FROM w.created_at) as day_of_week,\n      COUNT(*) as words_count\n    FROM words w\n    JOIN notebooks n ON w.notebook_id = n.id\n    WHERE n.user_id = auth.uid()\n      AND w.created_at >= CURRENT_DATE - INTERVAL '30 days'\n    GROUP BY EXTRACT(DOW FROM w.created_at)\n  ),\n  mastery_stats AS (\n    SELECT \n      COUNT(*) as total_words,\n      COUNT(CASE WHEN w.is_mastered THEN 1 END) as mastered_words\n    FROM words w\n    JOIN notebooks n ON w.notebook_id = n.id\n    WHERE n.user_id = auth.uid()\n  )\n  SELECT \n    ms.mastered_words::bigint as total_words_learned,\n    ws.mastered_this_week::bigint as words_mastered_this_week,\n    CASE \n      WHEN ms.total_words > 0 \n      THEN ROUND((ms.mastered_words::numeric / ms.total_words::numeric) * 100, 1)\n      ELSE 0\n    END as average_mastery_rate,\n    CASE (SELECT day_of_week FROM daily_counts ORDER BY words_count DESC LIMIT 1)\n      WHEN 0 THEN 'Sunday'\n      WHEN 1 THEN 'Monday'\n      WHEN 2 THEN 'Tuesday'\n      WHEN 3 THEN 'Wednesday'\n      WHEN 4 THEN 'Thursday'\n      WHEN 5 THEN 'Friday'\n      WHEN 6 THEN 'Saturday'\n      ELSE 'Monday'\n    END as most_productive_day,\n    user_profile_data.streak_count as current_streak,\n    user_profile_data.longest_streak as longest_streak,\n    GREATEST(15, LEAST(30, COALESCE(user_profile_data.total_words_added, 0) / GREATEST(1, EXTRACT(days FROM (CURRENT_DATE - user_profile_data.created_at::date)) + 1))) as recommended_daily_target\n  FROM mastery_stats ms\n  CROSS JOIN weekly_stats ws;\nEND;\n$function$\n"
  },
  {
    "proname": "get_notebook_stats",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_notebook_stats(p_notebook_id uuid)\n RETURNS TABLE(notebook_id uuid, total_words bigint, mastered_words bigint, round_1_words bigint, round_2_words bigint, round_3_words bigint, round_4_words bigint, pending_reviews bigint, words_added_today bigint, last_activity_date date)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  -- Check if user owns this notebook\n  IF NOT EXISTS (\n    SELECT 1 FROM notebooks \n    WHERE id = p_notebook_id AND user_id = auth.uid()\n  ) THEN\n    RAISE EXCEPTION 'Notebook not found or access denied';\n  END IF;\n  \n  RETURN QUERY\n  SELECT \n    p_notebook_id as notebook_id,\n    COUNT(*)::bigint as total_words,\n    COUNT(CASE WHEN w.is_mastered THEN 1 END)::bigint as mastered_words,\n    COUNT(CASE WHEN w.current_round = 1 THEN 1 END)::bigint as round_1_words,\n    COUNT(CASE WHEN w.current_round = 2 THEN 1 END)::bigint as round_2_words,\n    COUNT(CASE WHEN w.current_round = 3 THEN 1 END)::bigint as round_3_words,\n    COUNT(CASE WHEN w.current_round = 4 THEN 1 END)::bigint as round_4_words,\n    COUNT(CASE WHEN w.review_date <= CURRENT_DATE AND NOT w.is_mastered THEN 1 END)::bigint as pending_reviews,\n    COUNT(CASE WHEN DATE(w.created_at) = CURRENT_DATE THEN 1 END)::bigint as words_added_today,\n    MAX(DATE(w.updated_at)) as last_activity_date\n  FROM words w\n  WHERE w.notebook_id = p_notebook_id;\nEND;\n$function$\n"
  },
  {
    "proname": "get_words_for_review",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_words_for_review(p_notebook_id uuid, p_round_number integer DEFAULT NULL::integer)\n RETURNS TABLE(id uuid, word text, translation text, example_sentence text, notes text, current_round integer, review_date date, times_reviewed integer, created_at timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  -- Check if user owns this notebook\n  IF NOT EXISTS (\n    SELECT 1 FROM notebooks \n    WHERE notebooks.id = p_notebook_id AND user_id = auth.uid()\n  ) THEN\n    RAISE EXCEPTION 'Notebook not found or access denied';\n  END IF;\n  \n  RETURN QUERY\n  SELECT \n    w.id,\n    w.word,\n    w.translation,\n    w.example_sentence,\n    w.notes,\n    w.current_round,\n    w.review_date,\n    w.times_reviewed,\n    w.created_at\n  FROM words w\n  WHERE w.notebook_id = p_notebook_id\n    AND w.review_date <= CURRENT_DATE\n    AND w.is_mastered = false\n    AND (p_round_number IS NULL OR w.current_round = p_round_number)\n  ORDER BY w.review_date ASC, w.created_at ASC;\nEND;\n$function$\n"
  },
  {
    "proname": "update_notebook_stats",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.update_notebook_stats()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  -- This function is called after words are inserted, updated, or deleted\n  -- It could update computed statistics if needed, but for now we use real-time queries\n  \n  -- Update the notebook's updated_at timestamp\n  UPDATE notebooks \n  SET updated_at = NOW() \n  WHERE id = COALESCE(NEW.notebook_id, OLD.notebook_id);\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$function$\n"
  },
  {
    "proname": "update_user_stats",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.update_user_stats()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  user_id uuid;\n  total_words_count integer;\n  mastered_words_count integer;\nBEGIN\n  -- Get the user_id from the notebook\n  SELECT n.user_id INTO user_id\n  FROM notebooks n\n  WHERE n.id = COALESCE(NEW.notebook_id, OLD.notebook_id);\n  \n  -- Calculate updated statistics\n  SELECT \n    COUNT(*),\n    COUNT(CASE WHEN w.is_mastered THEN 1 END)\n  INTO total_words_count, mastered_words_count\n  FROM words w\n  JOIN notebooks n ON w.notebook_id = n.id\n  WHERE n.user_id = user_id;\n  \n  -- Update user profile statistics\n  UPDATE profiles \n  SET \n    total_words_added = total_words_count,\n    total_words_mastered = mastered_words_count,\n    updated_at = NOW()\n  WHERE id = user_id;\n  \n  RETURN COALESCE(NEW, OLD);\nEND;\n$function$\n"
  },
  {
    "proname": "update_daily_streak",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.update_daily_streak()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  current_streak integer;\n  last_activity_date date;\n  today_activity boolean;\nBEGIN\n  -- Get current profile data\n  SELECT \n    streak_count, \n    last_activity_date\n  INTO current_streak, last_activity_date\n  FROM profiles \n  WHERE id = auth.uid();\n  \n  -- Check if user has activity today\n  SELECT EXISTS (\n    SELECT 1 FROM words w\n    JOIN notebooks n ON w.notebook_id = n.id\n    WHERE n.user_id = auth.uid()\n    AND (\n      DATE(w.created_at) = CURRENT_DATE OR \n      DATE(w.last_reviewed) = CURRENT_DATE\n    )\n  ) INTO today_activity;\n  \n  IF today_activity THEN\n    -- User has activity today\n    IF last_activity_date = CURRENT_DATE THEN\n      -- Already updated today, return current streak\n      RETURN current_streak;\n    ELSIF last_activity_date = CURRENT_DATE - INTERVAL '1 day' THEN\n      -- Consecutive day, increment streak\n      current_streak := current_streak + 1;\n    ELSE\n      -- Streak broken, reset to 1\n      current_streak := 1;\n    END IF;\n    \n    -- Update profile\n    UPDATE profiles \n    SET \n      streak_count = current_streak,\n      longest_streak = GREATEST(longest_streak, current_streak),\n      last_activity_date = CURRENT_DATE,\n      updated_at = NOW()\n    WHERE id = auth.uid();\n    \n  ELSE\n    -- No activity today\n    IF last_activity_date < CURRENT_DATE - INTERVAL '1 day' THEN\n      -- Streak is broken\n      current_streak := 0;\n      UPDATE profiles \n      SET \n        streak_count = 0,\n        updated_at = NOW()\n      WHERE id = auth.uid();\n    END IF;\n  END IF;\n  \n  RETURN current_streak;\nEND;\n$function$\n"
  },
  {
    "proname": "get_notebook_round4_failures",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_notebook_round4_failures(p_notebook_id uuid, p_notebook_level text DEFAULT 'bronze'::text)\n RETURNS TABLE(word_id uuid, word text, meaning text, translation text, notes text, original_page_id uuid, page_number integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        w.id as word_id,\n        w.word,\n        w.meaning,\n        w.translation,\n        w.notes,\n        w.page_id as original_page_id,\n        p.page_number\n    FROM words w\n    JOIN pages p ON w.page_id = p.id\n    JOIN notebooks n ON w.notebook_id = n.id\n    WHERE w.notebook_id = p_notebook_id\n      AND n.notebook_level = p_notebook_level::notebook_level_enum\n      AND w.current_round = 4\n      AND w.status = 'failed'\n      AND NOT w.is_mastered;\nEND;\n$function$\n"
  },
  {
    "proname": "create_silver_notebook",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.create_silver_notebook(p_bronze_notebook_id uuid)\n RETURNS notebooks\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    bronze_notebook notebooks%ROWTYPE;\n    new_silver_notebook notebooks%ROWTYPE;\nBEGIN\n    -- Get the Bronze notebook details\n    SELECT * INTO bronze_notebook \n    FROM notebooks \n    WHERE id = p_bronze_notebook_id AND notebook_level = 'bronze';\n    \n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Bronze notebook not found: %', p_bronze_notebook_id;\n    END IF;\n    \n    -- Create Silver notebook with same settings\n    INSERT INTO notebooks (\n        user_id,\n        title,\n        language,\n        language_code,\n        notebook_level,\n        words_per_day,\n        review_interval_days,\n        is_active,\n        settings\n    ) VALUES (\n        bronze_notebook.user_id,\n        bronze_notebook.title || ' - Silver',\n        bronze_notebook.language,\n        bronze_notebook.language_code,\n        'silver',\n        bronze_notebook.words_per_day,\n        bronze_notebook.review_interval_days,\n        true,\n        bronze_notebook.settings\n    ) RETURNING * INTO new_silver_notebook;\n    \n    RETURN new_silver_notebook;\nEND;\n$function$\n"
  },
  {
    "proname": "update_subscription_status",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.update_subscription_status(p_user_id uuid, p_status text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_transaction_id text DEFAULT NULL::text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  -- Validate subscription status\n  IF p_status NOT IN ('free', 'weekly', 'annual') THEN\n    RAISE EXCEPTION 'Invalid subscription status: %', p_status;\n  END IF;\n  \n  -- Update profile\n  UPDATE profiles \n  SET \n    subscription_status = p_status,\n    subscription_expires_at = p_expires_at,\n    subscription_transaction_id = p_transaction_id,\n    updated_at = NOW()\n  WHERE id = p_user_id;\n  \n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'User profile not found';\n  END IF;\n  \n  -- Log subscription change\n  INSERT INTO subscription_logs (\n    user_id,\n    status,\n    expires_at,\n    transaction_id\n  ) VALUES (\n    p_user_id,\n    p_status,\n    p_expires_at,\n    p_transaction_id\n  );\nEND;\n$function$\n"
  },
  {
    "proname": "handle_new_user",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nBEGIN\n    -- Insert into profiles table\n    INSERT INTO public.profiles (\n        id,\n        email,\n        display_name,\n        subscription_status,\n        created_at,\n        updated_at\n    ) VALUES (\n        NEW.id,\n        NEW.email,\n        COALESCE(NEW.raw_user_meta_data->>'display_name', split_part(NEW.email, '@', 1)),\n        'free'::subscription_status,\n        NOW(),\n        NOW()\n    );\n    \n    RETURN NEW;\nEXCEPTION\n    WHEN OTHERS THEN\n        -- Log the error (optional)\n        RAISE LOG 'Error in handle_new_user: %', SQLERRM;\n        -- Return NEW anyway to not break user creation\n        RETURN NEW;\nEND;\n$function$\n"
  },
  {
    "proname": "create_gold_notebook",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.create_gold_notebook(p_silver_notebook_id uuid)\n RETURNS notebooks\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    silver_notebook notebooks%ROWTYPE;\n    bronze_notebook notebooks%ROWTYPE;\n    new_gold_notebook notebooks%ROWTYPE;\nBEGIN\n    -- Get the Silver notebook details\n    SELECT * INTO silver_notebook \n    FROM notebooks \n    WHERE id = p_silver_notebook_id AND notebook_level = 'silver';\n    \n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Silver notebook not found: %', p_silver_notebook_id;\n    END IF;\n    \n    -- Get the original Bronze notebook title (remove \" - Silver\" suffix)\n    SELECT * INTO bronze_notebook\n    FROM notebooks \n    WHERE user_id = silver_notebook.user_id \n      AND language = silver_notebook.language\n      AND notebook_level = 'bronze'\n    LIMIT 1;\n    \n    -- Create Gold notebook with same settings\n    INSERT INTO notebooks (\n        user_id,\n        title,\n        language,\n        language_code,\n        notebook_level,\n        words_per_day,\n        review_interval_days,\n        is_active,\n        settings\n    ) VALUES (\n        silver_notebook.user_id,\n        COALESCE(bronze_notebook.title, silver_notebook.title) || ' - Gold',\n        silver_notebook.language,\n        silver_notebook.language_code,\n        'gold',\n        silver_notebook.words_per_day,\n        silver_notebook.review_interval_days,\n        true,\n        silver_notebook.settings\n    ) RETURNING * INTO new_gold_notebook;\n    \n    RETURN new_gold_notebook;\nEND;\n$function$\n"
  },
  {
    "proname": "migrate_words_to_silver",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.migrate_words_to_silver(p_bronze_notebook_id uuid, p_silver_notebook_id uuid, p_failed_word_ids uuid[])\n RETURNS SETOF words\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    word_record RECORD;\n    new_word words%ROWTYPE;\n    silver_notebook notebooks%ROWTYPE;\n    current_page_id UUID;\n    words_in_current_page INTEGER := 0;\n    current_page_number INTEGER;\n    max_page_number INTEGER;\nBEGIN\n    -- Get Silver notebook details\n    SELECT * INTO silver_notebook FROM notebooks WHERE id = p_silver_notebook_id;\n    \n    -- Find the highest existing page number in Silver notebook\n    SELECT COALESCE(MAX(page_number), 0) INTO max_page_number\n    FROM pages \n    WHERE notebook_id = p_silver_notebook_id;\n    \n    -- Start from the next available page number\n    current_page_number := max_page_number + 1;\n    \n    -- Create first page in Silver notebook with page-based review fields\n    INSERT INTO pages (\n        notebook_id,\n        page_number,\n        date_created,\n        target_round,\n        page_completion_date,\n        page_current_round,\n        page_status,\n        page_review_date\n    ) VALUES (\n        p_silver_notebook_id,\n        current_page_number,\n        CURRENT_DATE,\n        '1'::round_number,\n        CURRENT_DATE, -- Page completion date is when migration happens\n        1, -- Start at Round 1\n        'active', -- Ready for review\n        CURRENT_DATE + INTERVAL '14 days' -- First review in 14 days\n    ) RETURNING id INTO current_page_id;\n    \n    -- Migrate each failed word\n    FOR word_record IN \n        SELECT w.*, p.page_number as original_page_number\n        FROM words w\n        JOIN pages p ON w.page_id = p.id\n        WHERE w.id = ANY(p_failed_word_ids)\n        ORDER BY p.page_number, w.position_in_page\n    LOOP\n        -- Check if we need a new page (reached words_per_day limit)\n        IF words_in_current_page >= silver_notebook.words_per_day THEN\n            current_page_number := current_page_number + 1;\n            words_in_current_page := 0;\n            \n            -- Create new page with page-based review fields\n            INSERT INTO pages (\n                notebook_id,\n                page_number,\n                date_created,\n                target_round,\n                page_completion_date,\n                page_current_round,\n                page_status,\n                page_review_date\n            ) VALUES (\n                p_silver_notebook_id,\n                current_page_number,\n                CURRENT_DATE,\n                '1'::round_number,\n                CURRENT_DATE,\n                1,\n                'active',\n                CURRENT_DATE + INTERVAL '14 days'\n            ) RETURNING id INTO current_page_id;\n        END IF;\n        \n        -- Insert word into Silver notebook (reset to Round 1)\n        INSERT INTO words (\n            notebook_id,\n            page_id,\n            word,\n            meaning,\n            translation,\n            notes,\n            current_round,\n            status,\n            review_date,\n            source_notebook_id,\n            original_page_id,\n            position_in_page\n        ) VALUES (\n            p_silver_notebook_id,\n            current_page_id,\n            word_record.word,\n            word_record.meaning,\n            word_record.translation,\n            word_record.notes,\n            1, -- Reset to Round 1 in Silver\n            'learning',\n            CURRENT_DATE + INTERVAL '14 days', -- New 14-day timer\n            p_bronze_notebook_id, -- Track original Bronze notebook\n            word_record.page_id, -- Track original Bronze page\n            words_in_current_page + 1\n        ) RETURNING * INTO new_word;\n        \n        words_in_current_page := words_in_current_page + 1;\n        \n        -- Mark original Bronze word as failed (moved to Silver)\n        UPDATE words \n        SET status = 'failed' \n        WHERE id = word_record.id;\n        \n        RETURN NEXT new_word;\n    END LOOP;\n    \n    -- Update page stats for all created pages\n    UPDATE pages \n    SET \n        words_count = (SELECT COUNT(*) FROM words WHERE page_id = pages.id),\n        is_completed = (SELECT COUNT(*) FROM words WHERE page_id = pages.id) > 0\n    WHERE notebook_id = p_silver_notebook_id;\n    \n    RETURN;\nEND;\n$function$\n"
  },
  {
    "proname": "get_pages_due_for_review",
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.get_pages_due_for_review(p_user_id uuid, p_current_date date DEFAULT CURRENT_DATE)\n RETURNS TABLE(page_id uuid, notebook_id uuid, notebook_title text, notebook_level text, page_number integer, page_current_round integer, page_review_date date, words_count integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        p.id as page_id,\n        p.notebook_id,\n        n.title as notebook_title,\n        n.notebook_level::TEXT,\n        p.page_number,\n        p.page_current_round,\n        p.page_review_date,\n        (SELECT COUNT(*)::INTEGER FROM words w WHERE w.page_id = p.id) as words_count\n    FROM pages p\n    JOIN notebooks n ON p.notebook_id = n.id\n    WHERE n.user_id = p_user_id\n      AND n.notebook_level IN ('silver', 'gold')\n      AND p.page_status = 'active'\n      AND p.page_review_date <= p_current_date\n    ORDER BY p.page_review_date ASC, n.notebook_level ASC, p.page_number ASC;\nEND;\n$function$\n"
  }
]
